import * as E from './engine.js';
import {Renderer,thumbnail} from './renderer.js';
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={base:'<path d="m3 10 9-6 9 6v10H3Zm5 10v-7h8v7M7 8V3h4"/>',army:'<path d="m12 3 8 4v6c0 5-8 8-8 8s-8-3-8-8V7Zm0 4v10M8 10l8 4m0-4-8 4"/>',missions:'<path d="m5 21 2-17 5 2 5-2 3 3-4 4-5-1-4 2M7 4V2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01"/>',target:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',pin:'<path d="M18 9c0 5-6 12-6 12S6 14 6 9a6 6 0 1 1 12 0Z"/><circle cx="12" cy="9" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',village:'<path d="M4 21v-9l5-4 5 4v9M14 21V6l4-3 4 3v15M7 21v-5h4v5M1 12l8-6 7 6"/>',terrain:'<path d="m2 18 6-10 4 6 4-10 6 14ZM5 21h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.base}</svg>`;
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const key='auralis-frontier-save-v1',now=Date.now();let storageOk=true,corrupt=false,state;
try{const raw=localStorage.getItem(key);state=raw?E.readSave(raw,now):null;corrupt=!!raw&&!state;if(corrupt)localStorage.setItem(key+'-recovery',raw);}catch{storageOk=false;}
state??=E.createGame(now);
// Offline production is capped at four hours; combat only progresses while visible.
E.advance(state,now);
if(!state.raid&&!state.battle&&state.nextRaidAt<now)state.nextRaidAt=now+60000;
let view='base',selected='hq',placement=null,terrainTool=null,moving=null,deployType='ranger',installPrompt=null,lastSave=0,lastUi=0,toastTimer,finishedShown=false;
const renderer=new Renderer($('#game'));
const fmt=n=>Math.floor(n).toLocaleString('es-CO'),time=n=>{const t=Math.ceil(Math.max(0,n));return `${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toString().padStart(2,'0')}`;};
const resourceSymbol={credits:'◈',alloy:'⬡',energy:'ϟ'},resourceName={credits:'áureos',alloy:'aleación',energy:'éter'};
function costs(cost){return `<div class="cost">${Object.entries(cost).map(([k,v])=>`<span class="${state.resources[k]<v?'lacking':''}"><i class="${k}">${resourceSymbol[k]}</i>${fmt(v)}</span>`).join('')}</div>`;}
function thumbs(root=document){root.querySelectorAll('canvas[data-thumb]').forEach(el=>thumbnail(el,el.dataset.thumb,el.dataset.unit==='true'));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOk=true;}catch{storageOk=false;}$('#save-status').textContent=storageOk?'GUARDADO LOCAL':'SIN GUARDAR';lastSave=Date.now();}
function act(result){if(result?.message)toast(result.message);if(result?.ok){save();updateResources();renderSidebar();if(view!=='base')renderPanel();renderDock();}return result;}
function openModal(html){$('#modal-content').innerHTML=html;thumbs($('#modal'));if(!$('#modal').open)$('#modal').showModal();}
function modalHead(label,title){return `<div class="modal-header"><div class="eyebrow"><span></span>${label}</div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">×</button></div><h2>${title}</h2>`;}
function guide(){openModal(modalHead('BIENVENIDO A LA FRONTERA','Tu mundo. Tu estrategia.')+`<p>Dirige una colonia donde la tecnología se encuentra con la magia. Construye, comercia y defiende tu territorio.</p><div class="guide-grid"><div class="guide-step"><b>01 · CONSTRUYE</b><p>Elige un edificio y toca terreno libre. Toca edificios para mejorarlos, moverlos o repararlos.</p></div><div class="guide-step"><b>02 · COMERCIA</b><p>Produce aleación y éter. Ayuda a los NPC del poblado para ganar áureos, la moneda de la frontera.</p></div><div class="guide-step"><b>03 · DEFIENDE</b><p>La IA enviará incursiones. Torres, santuarios y tropas en la base defienden automáticamente.</p></div><div class="guide-step"><b>04 · CONQUISTA</b><p>Entrena un ejército y ataca las fortalezas. Selecciona tropas y toca la zona azul para desplegarlas.</p></div></div><p>Arrastra el mapa para explorar. Usa + y − para acercar. En «Terreno» puedes allanar, elevar, excavar, plantar y crear caminos por 25 áureos por casilla.</p><button class="primary" data-action="close-modal">COMENZAR MI COLONIA ${icon('arrow')}</button>`);state.tutorialSeen=true;save();}
function setView(next){
  if(state.battle||state.raid){if(next!=='base'){toast('Termina el combate antes de abrir este apartado.');return;}}
  view=next;placement=null;terrainTool=null;moving=null;
  $$('.nav-btn[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===next));
  $('#panel').classList.toggle('open',next!=='base');$('#placement-bar').hidden=true;
  renderPanel();renderDock();renderSidebar();
}
function updateResources(){const rates=E.production(state);for(const k of ['credits','alloy','energy']){$('#'+k).textContent=fmt(state.resources[k]);$('#'+k+'-rate').textContent='+'+(Math.round(rates[k]*10)/10)+'/s';}$('#level').textContent='Nivel '+(1+Math.floor(state.xp/200));}
const missionArt=`<svg viewBox="0 0 320 180" aria-hidden="true"><path d="m0 104 57-45 55 40 69-66 91 62 48-24v109H0Z" fill="#777855"/><path d="m0 140 89-59 62 50 74-65 95 65v49H0Z" fill="#5c684b"/><path d="m50 157 79-44 92 40-83 27Z" fill="#344b42"/><path d="m117 115 35-19 34 18v32l-35 18-34-19Z" fill="#8d8f6a"/><path d="m117 115 34 17 35-18-34-18Z" fill="#c2bc8c"/><path d="m151 132 35-18v32l-35 18Z" fill="#66765a"/><path d="m142 113 10-6 10 6-10 6Z" fill="#b5d8b9"/><path d="M221 110v-48m0 0 23 9-23 6" fill="#c3c19a" stroke="#3c5044" stroke-width="3"/><path d="m218 139 22-12 22 12v20l-22 12-22-12Z" fill="#5b7158"/><path d="m218 139 22-12 22 12-22 12Z" fill="#a0a67a"/><path d="m235 137 8-5 8 5-8 5Z" fill="#d3aa77"/></svg>`;
function renderSidebar(){
  const side=$('#sidebar');if(state.battle){const m=E.MISSIONS[state.battle.mission],alive=state.battle.enemies.filter(e=>e.hp>0).length;side.innerHTML=`<div class="section-label">OPERATION FRONTIER</div><div class="mission-art">${missionArt}<span>${m.region}</span></div><h2>${m.name}</h2><p>Selecciona una unidad en la barra inferior y toca la zona azul para desplegarla. El ejército ataca las defensas cercanas automáticamente.</p><div class="building-info"><span>Objetivos enemigos</span><strong>${alive} / ${state.battle.enemies.length}</strong></div><div class="building-info"><span>Unidades en reserva</span><strong>${E.unitCount(state.battle.reserve)}</strong></div><div class="building-info"><span>En combate</span><strong>${state.battle.units.filter(u=>u.hp>0).length}</strong></div><p style="margin-top:20px">Destruye todas las defensas y el núcleo antes de 3 minutos. Las tropas supervivientes volverán a casa.</p><div class="section-label" style="margin-top:25px">BOTÍN DEL SECTOR</div><div class="reward-row">${rewardHtml(m.reward)}</div>`;return;}
  if(state.raid){side.innerHTML=`<div class="section-label">ALERTA DE INCURSIÓN</div><h2>Defiende Aurora.</h2><p>Los saqueadores del Eclipse están atacando tu base. Tus torres, santuarios y guarnición disparan automáticamente.</p><div class="building-info"><span>Invasores activos</span><strong>${state.raid.units.filter(u=>u.hp>0).length}</strong></div><div class="building-info"><span>Edificios operativos</span><strong>${state.buildings.filter(b=>b.hp>0).length}</strong></div><p style="margin-top:20px">Si el centro de mando cae, el enemigo saqueará el 15% de tus áureos. Después podrás reparar la base.</p>`;return;}
  const b=state.buildings.find(b=>b.id===selected);
  if(b&&selected!=='hq'){
    const spec=E.BUILDINGS[b.type],max=spec.hp*b.level;
    side.innerHTML=`<div class="section-label">GESTIONAR EDIFICIO</div><div class="building-hero"><canvas data-thumb="${b.type}"></canvas></div><div class="mission-kicker"><span>${spec.tag}</span><b>NIVEL ${b.level} / 5</b></div><h2>${spec.name}</h2><p>${spec.description}</p><div class="building-info"><span>Integridad</span><strong>${Math.ceil(b.hp)} / ${max}</strong></div>${Object.entries(spec.rate).map(([k,v])=>`<div class="building-info"><span>Producción de ${resourceName[k]}</span><strong>+${(v*b.level).toFixed(1)}/s</strong></div>`).join('')}${b.readyAt?`<p style="margin-top:15px" data-building-timer="${b.readyAt}">En obras: ${Math.ceil(Math.max(0,b.readyAt-Date.now())/1000)} s</p>`:''}<p style="margin:18px 0 8px">Mejora al nivel ${Math.min(5,b.level+1)}</p>${costs(E.upgradeCost(b))}<button class="primary" data-action="upgrade" data-id="${esc(b.id)}" ${!E.ready(b,Date.now())||b.level>=5?'disabled':''}>${b.level>=5?'NIVEL MÁXIMO':'MEJORAR EDIFICIO'} ${icon('arrow')}</button><div class="modal-actions"><button class="secondary" data-action="move" data-id="${esc(b.id)}">Mover</button><button class="secondary" data-action="repair" data-id="${esc(b.id)}" ${b.hp>=max?'disabled':''}>Reparar · ◈ ${Math.ceil((1-b.hp/max)*180*b.level)}</button></div><button class="text-link" data-action="clear-selection">← Volver al resumen</button>`;thumbs(side);return;
  }
  const m=E.MISSIONS[Math.min(state.campaign,2)],goals=[{text:'Construye tu economía',sub:'Dos edificios de producción',n:state.buildings.filter(b=>['mine','reactor','refinery'].includes(b.type)).length,total:3},{text:'Prepara tu ejército',sub:'Reúne doce unidades',n:E.unitCount(state.army),total:12},{text:'Ayuda al poblado',sub:'Completa encargos de los NPC',n:state.contracts,total:3}];
  side.innerHTML=`<div class="section-label">LA FRONTERA TE ESPERA</div><div class="mission-art">${missionArt}<span>${m.region}</span></div><div class="mission-kicker"><span>${state.campaign>=3?'CAMPAÑA COMPLETADA':'PRÓXIMA OPERACIÓN'}</span><b>VS. IA</b></div><h2>${m.name}</h2><p>${m.description}</p><span class="reward-label">RECOMPENSAS DE PRIMERA VICTORIA</span><div class="reward-row">${rewardHtml(m.reward)}</div><button class="primary" data-action="show-missions">EXPLORAR FRONTERA ${icon('arrow')}</button><div class="side-divider"></div><div class="section-label">OBJETIVOS DE LA COLONIA</div>${goals.map(g=>`<div class="objective ${g.n>=g.total?'done':''}"><span class="check">${g.n>=g.total?'✓':'·'}</span><span>${g.text}<small>${g.sub}</small></span><span class="counter">${Math.min(g.n,g.total)}/${g.total}</span></div>`).join('')}<div class="side-divider"></div><div class="base-status"><span>Próxima incursión</span><b id="raid-countdown">${time((state.nextRaidAt-Date.now())/1000)}</b></div><div class="progress"><i style="width:${Math.min(100,(Date.now()-(state.nextRaidAt-420000))/4200)}%"></i></div><button class="text-link" data-action="show-village">${state.offers.length?'● '+state.offers.length+' habitantes necesitan ayuda':'Visitar el poblado'} ${icon('arrow')}</button><div class="side-footer"><span>AURALIS FRONTIER</span><span>ALPHA 0.1</span></div>`;
}
function rewardHtml(reward){return Object.entries(reward).map(([k,v])=>`<span><i class="${k}">${resourceSymbol[k]}</i>${fmt(v)}</span>`).join('');}
function renderDock(){
  const dock=$('#dock');if(view!=='base'){dock.innerHTML='';return;}
  if(state.battle){dock.innerHTML=`<span class="dock-title">DESPLEGAR</span>${Object.entries(E.UNITS).map(([type,u])=>`<button class="build-card deploy-card ${deployType===type?'active':''}" data-action="select-unit" data-type="${type}" ${!state.battle.reserve[type]?'disabled':''}><div class="card-top"><span>${u.short}</span></div><div class="mini-art"><canvas data-thumb="${type}" data-unit="true"></canvas></div><span class="quantity">${state.battle.reserve[type]}</span><strong>Toca para seleccionar</strong></button>`).join('')}`;thumbs(dock);return;}
  if(state.raid){dock.innerHTML='<div class="raid-notice"><i class="live-dot"></i> INCURSIÓN ENEMIGA · Tus defensas protegen la base automáticamente.</div>';return;}
  if(terrainTool){const tools={flatten:['Allanar','▱'],raise:['Elevar','↟'],lower:['Excavar / agua','▽'],forest:['Plantar bosque','♧'],path:['Crear camino','═']};dock.innerHTML=`<span class="dock-title">TERRAFORMAR</span>${Object.entries(tools).map(([t,[name,symbol]])=>`<button class="build-card terrain-card ${terrainTool===t?'active':''}" data-action="terrain" data-tool="${t}"><div class="card-top"><span>TERRENO</span></div><div class="terrain-symbol">${symbol}</div><strong>${name}</strong><div class="cost"><span><i class="credits">◈</i>25 / casilla</span></div></button>`).join('')}`;return;}
  dock.innerHTML=`<span class="dock-title">CONSTRUIR</span>${Object.entries(E.BUILDINGS).filter(([type])=>type!=='command').map(([type,b],i)=>`<button class="build-card ${placement===type?'active':''}" data-action="select-build" data-type="${type}"><div class="card-top"><span>${b.tag}</span><span>0${i+1}</span></div><div class="mini-art"><canvas data-thumb="${type}"></canvas></div><strong>${b.name}</strong>${costs(b.cost)}</button>`).join('')}<button class="build-card terrain-card" data-action="terrain" data-tool="flatten"><div class="card-top"><span>PERSONALIZAR</span></div><div class="terrain-symbol">${icon('terrain')}</div><strong>Reformar terreno</strong><div class="cost"><span>Desde ◈ 25</span></div></button>`;thumbs(dock);
}
function panelHead(label,title,lead){return `<div class="panel-top"><div><div class="eyebrow"><span></span>${label}</div><h2>${title}</h2></div><button class="close-panel" data-action="close-panel" aria-label="Volver al mapa">×</button></div><p class="panel-lead">${lead}</p>`;}
function renderPanel(){
  const panel=$('#panel');if(view==='base'){panel.innerHTML='';return;}
  if(view==='army'){
    panel.innerHTML=panelHead('LA GUARNICIÓN DE AURORA','Un ejército a tu medida.','Tecnología, acero y magia. Las unidades disponibles defienden la base y pueden partir a la frontera.')+`<div class="unit-grid">${Object.entries(E.UNITS).map(([type,u])=>`<article class="unit-card"><div class="unit-visual"><canvas data-thumb="${type}" data-unit="true"></canvas></div><div><div class="mission-kicker"><span>${state.army[type]} DISPONIBLES</span></div><h3>${u.name}</h3></div><p>${u.description}</p><div class="unit-stats"><span>VIDA<strong>${u.hp}</strong></span><span>DAÑO<strong>${u.damage}</strong></span><span>TIEMPO<strong>${u.time} s</strong></span></div>${costs(u.cost)}<button class="primary" data-action="train" data-type="${type}">ENTRENAR ${icon('arrow')}</button></article>`).join('')}</div><div class="queue"><h3>COLA DE ENTRENAMIENTO <span>· ${state.jobs.length} / 8</span></h3><div class="queue-list">${state.jobs.length?state.jobs.map((j,i)=>`<div class="queue-item"><span>${i+1}. ${E.UNITS[j.unit].name}</span><strong data-queue-time="${j.readyAt}">${time((j.readyAt-Date.now())/1000)}</strong></div>`).join(''):'<span class="queue-empty">El cuartel está listo. Elige una unidad para comenzar.</span>'}</div><p class="queue-empty">Población: ${E.unitCount(state.army)+state.jobs.length} / 60 · Las mejoras de cuartel aceleran el entrenamiento.</p></div>`;
  }else if(view==='missions'){
    panel.innerHTML=panelHead('LA CAMPAÑA DE LA FRONTERA','Más allá de Aurora.','Ataca las fortalezas de la IA y captura sus riquezas. Las ciudadelas avanzadas exigen tropas y defensas mejoradas.')+(state.campaign>=3?'<div class="mission-complete"><h3>La frontera es tuya.</h3><p>Has liberado los tres sectores. Puedes repetir operaciones por el 35% del botín y seguir expandiendo tu colonia.</p></div>':'')+`<div class="mission-list">${E.MISSIONS.map((m,i)=>`<article class="mission-card ${i>state.campaign?'locked':''}"><div class="mission-number">0${i+1}</div><div><div class="eyebrow">${m.region} ${i<state.campaign?'· ✓ LIBERADO':''}</div><h3>${m.name}</h3><p>${m.description}</p><div class="reward-row">${rewardHtml(Object.fromEntries(Object.entries(m.reward).map(([k,v])=>[k,Math.floor(v*(i<state.campaign?.35:1))])))}</div></div><button class="primary" data-action="start-mission" data-index="${i}" ${i>state.campaign?'disabled':''}>${i>state.campaign?'BLOQUEADO':i<state.campaign?'VOLVER A ATACAR':'INICIAR ATAQUE'} ${icon('arrow')}</button></article>`).join('')}</div><p class="panel-lead" style="margin-top:20px">${E.unitCount(state.army)} unidades listas. Las tropas caídas se pierden; las supervivientes regresan. Los enemigos también atacan tu base: prepara sus defensas.</p>`;
  }else if(view==='village'){
    panel.innerHTML=panelHead('CARAVANAS Y HABITANTES','El poblado te necesita.','Los viajeros llegan con encargos. Entrega recursos y recibe áureos para construir, mejorar y entrenar.')+`<div class="npc-list">${state.offers.length?state.offers.map(o=>{const n=E.NPCS[o.kind];return `<article class="npc-card"><div class="npc-avatar npc-${o.kind}">${['M','E','N'][o.kind]}<i>!</i></div><div class="npc-copy"><div class="eyebrow">${n.role}</div><h3>${n.name}</h3><p>«${n.text}»</p><div class="npc-trade"><span>Entregar <b>${o.amount} ${resourceName[o.resource]}</b></span><span>Recibir <b class="credits">◈ ${fmt(o.reward)}</b></span></div><small data-npc-time="${o.expiresAt}">Se marcha en ${time((o.expiresAt-Date.now())/1000)}</small></div><button class="primary" data-action="fulfill" data-id="${o.id}" ${state.resources[o.resource]<o.amount?'disabled':''}>AYUDAR ${icon('arrow')}</button></article>`;}).join(''):'<div class="empty-village"><div class="terrain-symbol">'+icon('village')+'</div><h3>Una caravana está en camino.</h3><p>Próxima visita en <b id="npc-countdown">'+time((state.nextNpcAt-Date.now())/1000)+'</b>. Sigue produciendo recursos mientras llega.</p></div>'}</div><div class="queue"><h3>MERCADO DE AURORA</h3><p class="panel-lead">Convierte tus excedentes en moneda. Los encargos de los habitantes pagan una tarifa mayor.</p><div class="market-grid">${['alloy','energy'].map(k=>`<div class="market-card"><span class="resource-icon ${k}">${resourceSymbol[k]}</span><strong>50 ${resourceName[k]}</strong><span>◈ 75 áureos</span><button class="secondary" data-action="trade" data-resource="${k}" ${state.resources[k]<50?'disabled':''}>Vender 50</button></div>`).join('')}</div></div><p class="queue-empty">${state.contracts} encargos completados · Los NPC se renuevan mientras juegas y cada visita dura 5 minutos.</p>`;
  }
  thumbs(panel);
}
function buildingModal(id){const b=state.buildings.find(b=>b.id===id);if(!b)return;const spec=E.BUILDINGS[b.type],max=spec.hp*b.level;openModal(modalHead(spec.tag,spec.name)+`<div class="building-hero"><canvas data-thumb="${b.type}"></canvas></div><p>${spec.description}</p><div class="building-info"><span>Nivel</span><strong>${b.level} / 5</strong></div><div class="building-info"><span>Integridad</span><strong>${Math.ceil(b.hp)} / ${max}</strong></div>${b.readyAt?`<p>En obras · <span data-building-timer="${b.readyAt}">${time((b.readyAt-Date.now())/1000)}</span></p>`:''}<p>Coste de mejora:</p>${costs(E.upgradeCost(b))}<div class="modal-actions"><button class="primary" data-action="upgrade" data-id="${esc(id)}" ${!E.ready(b,Date.now())||b.level>=5?'disabled':''}>MEJORAR</button><button class="secondary" data-action="move" data-id="${esc(id)}">Mover</button><button class="secondary" data-action="repair" data-id="${esc(id)}" ${b.hp>=max?'disabled':''}>Reparar · ◈ ${Math.ceil((1-b.hp/max)*180*b.level)}</button></div>`);}
function settings(){openModal(modalHead('CENTRO DE MANDO','Tu partida, a salvo.')+`<p>La partida se guarda en este dispositivo. Exporta una copia para continuar en otra computadora o celular. Las partidas de la web, Android y Windows son independientes hasta que importes esa copia.</p>${!storageOk?'<p class="warning">El navegador no permite guardar. Exporta una copia antes de cerrar.</p>':''}<div class="settings-row"><div><strong>Exportar partida</strong><p>Descarga una copia de tus recursos, base y progreso.</p></div><button class="secondary" data-action="export">Exportar JSON</button></div><div class="settings-row"><div><strong>Importar partida</strong><p>Reemplaza la partida de este dispositivo por una copia.</p></div><button class="secondary" data-action="import">Elegir archivo</button></div><div class="settings-row"><div><strong>Instalar y descargar</strong><p>Web instalable, Android y Windows.</p></div><button class="secondary" data-action="downloads">Ver opciones</button></div><div class="settings-row"><div><strong>Guía de la frontera</strong><p>Construcción, terreno, encargos y combate.</p></div><button class="secondary" data-action="guide">Cómo jugar</button></div><button class="text-link danger" data-action="reset-confirm" style="margin-top:20px">Borrar el progreso y empezar de nuevo</button><p style="font-size:10px">Auralis Frontier · Alpha 0.1 · Juego original para un jugador. La IA se simula en tu dispositivo; las incursiones y los combates se pausan al cerrar o cambiar de pestaña.</p>`);}
function downloads(){openModal(modalHead('LLEVA LA FRONTERA CONTIGO','Juega donde quieras.')+`<p>Instala la versión web o descarga el juego completo. Android y Windows incluyen los archivos para jugar sin conexión.</p><div class="download-grid"><a class="download-option" href="https://github.com/OscarD0823/auralis-frontier/releases/latest/download/Auralis-Frontier-Android.apk"><span>ANDROID</span><strong>Descargar APK ${icon('download')}</strong><small>Android 7 o posterior · Instalación directa</small></a><a class="download-option" href="https://github.com/OscarD0823/auralis-frontier/releases/latest/download/Auralis-Frontier-Windows-Setup.exe"><span>WINDOWS</span><strong>Descargar instalador ${icon('download')}</strong><small>Windows 10/11 · 64 bits</small></a></div><button class="primary" data-action="install" style="margin-top:20px">INSTALAR VERSIÓN WEB ${icon('download')}</button><p id="install-instructions">${installPrompt?'Pulsa el botón para instalar desde este navegador.':/iPad|iPhone|iPod/.test(navigator.userAgent)?'En Safari: Compartir → Añadir a pantalla de inicio.':'En Chrome o Edge: abre el menú del navegador → Instalar aplicación / Añadir a pantalla de inicio. Abre el juego con conexión una vez para habilitar su uso sin conexión.'}</p><div class="modal-actions"><a class="secondary" href="https://oscard0823.github.io/Pagina-Principal/">Ecosistema Auralis</a><a class="secondary" href="https://github.com/OscarD0823/auralis-frontier/releases" target="_blank" rel="noopener">Todas las versiones</a></div>`);}
function choosePlacement(type){if(state.battle||state.raid)return;view='base';placement=type;terrainTool=null;moving=null;$('#panel').classList.remove('open');$('#placement-label').textContent='Construir '+E.BUILDINGS[type].name+' · Toca terreno libre';$('#placement-bar').hidden=false;renderDock();}
function cancel(){placement=null;terrainTool=null;moving=null;$('#placement-bar').hidden=true;renderDock();}
function showBattleResult(){if(finishedShown)return;finishedShown=true;const b=state.battle,m=E.MISSIONS[b.mission],win=b.outcome==='victory',alive=b.units.filter(u=>u.hp>0).length+E.unitCount(b.reserve),dead=b.units.filter(u=>u.hp<=0).length;openModal(`<div class="result-symbol">${win?'✦':'◇'}</div><div class="result-heading"><div class="eyebrow">${m.region}</div><h2>${win?'La victoria es tuya.':'La frontera resiste.'}</h2><p>${win?'Has destruido la fortaleza enemiga.':'Reorganiza tu ejército y vuelve con refuerzos.'}</p></div><div class="result-stats"><span><strong>${alive}</strong>supervivientes</span><span><strong>${dead}</strong>unidades caídas</span></div>${win?'<div class="reward-row" style="justify-content:center">'+rewardHtml(Object.fromEntries(Object.entries(m.reward).map(([k,v])=>[k,Math.floor(v*(b.mission<state.campaign?.35:1))])))+'</div>':''}<button class="primary" data-action="finish-battle" style="margin-top:25px">REGRESAR A LA BASE ${icon('arrow')}</button>`);}
document.addEventListener('click',async event=>{
  const nav=event.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return;}
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const a=button.dataset.action,id=button.dataset.id,type=button.dataset.type;
  if(a==='close-modal'){if(state.battle?.outcome||state.raid?.outcome)return;$('#modal').close();}
  else if(a==='close-panel')setView('base');
  else if(a==='show-missions')setView('missions');
  else if(a==='show-village')setView('village');
  else if(a==='select-build')choosePlacement(type);
  else if(a==='select-unit'){deployType=type;renderDock();toast(E.UNITS[type].name+' seleccionado. Toca la zona azul.');}
  else if(a==='train')act(E.train(state,type));
  else if(a==='upgrade'){const r=act(E.upgrade(state,id));if(r.ok&&$('#modal').open)buildingModal(id);}
  else if(a==='repair'){const r=act(E.repair(state,id));if(r.ok&&$('#modal').open)buildingModal(id);}
  else if(a==='move'){if(state.raid)return;moving=id;placement=null;terrainTool=null;$('#modal').close();setView('base');moving=id;$('#placement-label').textContent='Reubicar edificio · Toca terreno libre';$('#placement-bar').hidden=false;}
  else if(a==='clear-selection'){selected='hq';renderSidebar();}
  else if(a==='terrain'){if(state.battle||state.raid)return;terrainTool=button.dataset.tool;placement=null;moving=null;$('#placement-label').textContent='Reformar terreno · 25 áureos por casilla';$('#placement-bar').hidden=false;renderDock();}
  else if(a==='fulfill')act(E.fulfill(state,Number(id)));
  else if(a==='trade')act(E.trade(state,button.dataset.resource));
  else if(a==='start-mission'){
    const r=E.startBattle(state,Number(button.dataset.index));act(r);if(r.ok){finishedShown=false;selected=null;view='base';$('#panel').classList.remove('open');$('#modal').close();renderer.camera={x:0,y:0,zoom:1};$('#battle-bar').hidden=false;$('#field-eyebrow').textContent='TERRITORIO ENEMIGO';$('#field-title').textContent=E.MISSIONS[state.battle.mission].name;$('#field-subtitle').textContent='Despliega tu ejército y conquista la fortaleza.';$('#location-label').textContent=E.MISSIONS[state.battle.mission].region;$('#scene-hint').textContent='Selecciona una unidad y toca la zona azul para desplegar';deployType=Object.keys(state.battle.reserve).find(k=>state.battle.reserve[k])||'ranger';renderDock();renderSidebar();}
  }else if(a==='finish-battle'){act(E.finishBattle(state));returnToBase();}
  else if(a==='retreat-confirm'){act(E.finishBattle(state,true));returnToBase();}
  else if(a==='export'){
    save();const filename='Auralis-Frontier-'+new Date().toISOString().slice(0,10)+'.json',data=JSON.stringify(state,null,2);
    if(globalThis.Capacitor?.isNativePlatform?.()){
      try{const files=Capacitor.registerPlugin('Filesystem'),share=Capacitor.registerPlugin('Share'),result=await files.writeFile({path:filename,data,directory:'CACHE',encoding:'utf8'});await share.share({title:'Copia de Auralis Frontier',files:[result.uri],dialogTitle:'Guardar o compartir partida'});toast('Copia de la partida lista para guardar.');}catch{toast('No se pudo compartir la copia. Intenta exportarla de nuevo.');}
    }else{const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Copia de la partida exportada.');}
  }else if(a==='import')$('#import-input').click();
  else if(a==='confirm-import'){
    state=pendingImport;pendingImport=null;E.advance(state);if(!state.battle&&!state.raid&&state.nextRaidAt<Date.now())state.nextRaidAt=Date.now()+60000;save();returnToBase();if(state.battle)restoreBattleUi();toast('Partida importada.');
  }else if(a==='reset-confirm')openModal(modalHead('NUEVA PARTIDA','¿Empezar de nuevo?')+'<p>Se borrarán la base, el ejército y todo el progreso de este dispositivo. Exporta tu partida si quieres conservarla.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Cancelar</button><button class="primary" data-action="reset">BORRAR Y REINICIAR</button></div>');
  else if(a==='reset'){state=E.createGame();save();returnToBase();guide();}
  else if(a==='guide')guide();
  else if(a==='downloads')downloads();
  else if(a==='install'){if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice.outcome==='accepted')toast('Instalación solicitada.');installPrompt=null;}else toast('Usa el menú de tu navegador para instalar la aplicación.');}
  else if(a==='finish-raid'){const r=E.finishRaid(state);toast(r.message);save();returnToBase();}
});
function returnToBase(){$('#modal').close();$('#battle-bar').hidden=true;$('#field-eyebrow').textContent='TERRITORIO ALIADO';$('#field-title').textContent='Un nuevo comienzo.';$('#field-subtitle').textContent='Tecnología, magia y un mundo por construir.';$('#location-label').innerHTML='PUESTO AURORA <b>·</b> SECTOR 00';$('#scene-hint').innerHTML='Arrastra para explorar <span>·</span> Toca un edificio para gestionarlo';$('#retreat-btn').hidden=false;selected='hq';setView('base');renderer.camera={x:0,y:0,zoom:1};finishedShown=false;updateResources();}
function restoreBattleUi(){const b=state.battle;view='base';$('#panel').classList.remove('open');$('#battle-bar').hidden=false;$('#field-eyebrow').textContent='TERRITORIO ENEMIGO';$('#field-title').textContent=E.MISSIONS[b.mission].name;$('#field-subtitle').textContent='Despliega tu ejército y conquista la fortaleza.';$('#location-label').textContent=E.MISSIONS[b.mission].region;$('#scene-hint').textContent='Selecciona una unidad y toca la zona azul para desplegar';deployType=Object.keys(b.reserve).find(k=>b.reserve[k])||'ranger';renderDock();renderSidebar();}
let pendingImport=null;
$('#import-input').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>500000){toast('El archivo es demasiado grande. Elige una partida de Auralis Frontier.');return;}try{const parsed=E.readSave(await f.text());if(!parsed){toast('El archivo no contiene una partida válida. Tu progreso se ha conservado.');return;}pendingImport=parsed;openModal(modalHead('IMPORTAR PARTIDA','¿Restaurar esta colonia?')+`<p>Esta copia contiene ${parsed.buildings.length} edificios, ${fmt(parsed.resources.credits)} áureos y ${parsed.campaign} sectores liberados. Reemplazará tu partida actual.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Cancelar</button><button class="primary" data-action="confirm-import">RESTAURAR PARTIDA</button></div>`);}catch{toast('No se pudo leer el archivo. Tu partida se ha conservado.');}});
$('#modal').addEventListener('cancel',e=>{if(state.battle?.outcome||state.raid?.outcome)e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&!state.battle?.outcome&&!state.raid?.outcome)$('#modal').close();});
$('#settings-btn').addEventListener('click',()=>{if(state.battle?.outcome||state.raid?.outcome)return;settings();});
$('#help-btn').addEventListener('click',()=>{if(state.battle||state.raid){toast('Termina el combate antes de abrir la guía.');return;}guide();});
$('#downloads-btn').addEventListener('click',()=>{if(state.battle?.outcome||state.raid?.outcome)return;downloads();});
$('#cancel-placement').addEventListener('click',cancel);
$('#retreat-btn').addEventListener('click',()=>{if(!state.battle||state.battle.outcome)return;openModal(modalHead('REAGRUPAR EL EJÉRCITO','¿Ordenar la retirada?')+'<p>Las unidades supervivientes y las reservas regresarán a la base. Las unidades caídas se pierden y no recibirás botín.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Seguir luchando</button><button class="primary" data-action="retreat-confirm">RETIRARSE</button></div>');});
$('#zoom-in').addEventListener('click',()=>renderer.camera.zoom=Math.min(1.8,renderer.camera.zoom+.15));$('#zoom-out').addEventListener('click',()=>renderer.camera.zoom=Math.max(.5,renderer.camera.zoom-.15));$('#center-map').addEventListener('click',()=>renderer.camera={x:0,y:0,zoom:1});
let pointers=new Map(),pointerStart=null,lastPoint=null,dragged=false,pinchStart=null;
const canvas=$('#game');
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()];pinchStart={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:renderer.camera.zoom};dragged=true;}else{pointerStart={x:e.clientX,y:e.clientY};lastPoint=pointerStart;dragged=false;}});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();renderer.hover=renderer.tileAt(e.clientX-r.left,e.clientY-r.top,state);if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinchStart){const [a,b]=[...pointers.values()];renderer.camera.zoom=Math.max(.5,Math.min(1.8,pinchStart.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinchStart.distance)));return;}if(lastPoint){if(Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>6)dragged=true;if(dragged){renderer.camera.x=Math.max(-800,Math.min(800,renderer.camera.x+e.clientX-lastPoint.x));renderer.camera.y=Math.max(-500,Math.min(500,renderer.camera.y+e.clientY-lastPoint.y));}lastPoint={x:e.clientX,y:e.clientY};}});
canvas.addEventListener('pointerup',e=>{const wasMulti=pointers.size>1;pointers.delete(e.pointerId);if(wasMulti){pinchStart=null;lastPoint=null;return;}if(!dragged&&pointerStart){const rect=canvas.getBoundingClientRect(),px=e.clientX-rect.left,py=e.clientY-rect.top;mapTap(px,py);}lastPoint=null;pointerStart=null;});
canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);pointerStart=null;lastPoint=null;pinchStart=null;dragged=true;});
canvas.addEventListener('wheel',e=>{e.preventDefault();renderer.camera.zoom=Math.min(1.8,Math.max(.5,renderer.camera.zoom-e.deltaY*.001));},{passive:false});
function mapTap(px,py){const tile=renderer.tileAt(px,py,state);renderer.hover=tile;
  if(state.battle){if(state.battle.outcome)return;const p=renderer.unproject(px,py);act(E.deploy(state,deployType,p.x,p.y));return;}
  if(state.raid)return;
  if(placement){const r=act(E.build(state,placement,tile.x,tile.y));if(r.ok){selected=r.id;cancel();renderSidebar();}return;}
  if(moving){const r=act(E.moveBuilding(state,moving,tile.x,tile.y));if(r.ok)cancel();return;}
  if(terrainTool){act(E.reform(state,terrainTool,tile.x,tile.y));return;}
  // Pick by projected roof bounds before the ground tile, so tall buildings remain tappable.
  const picked=[...state.buildings].sort((a,b)=>(b.x+b.y)-(a.x+a.y)).find(b=>{const spec=E.BUILDINGS[b.type],p=renderer.p(b.x+spec.size/2,b.y+spec.size/2,(state.terrain[b.y*E.GRID+b.x].h||0)*10),scale=renderer.scale*renderer.camera.zoom;return Math.abs(px-p.x)<spec.size*24*scale&&py>p.y-66*scale&&py<p.y+spec.size*11*scale;});
  const b=picked||state.buildings.find(b=>tile.x>=b.x&&tile.x<b.x+E.BUILDINGS[b.type].size&&tile.y>=b.y&&tile.y<b.y+E.BUILDINGS[b.type].size);
  if(b){selected=b.id;renderSidebar();if(innerWidth<=900||b.type==='command')buildingModal(b.id);}
  else if(state.offers.length&&tile.x>=2&&tile.x<=4&&tile.y>=8&&tile.y<=10)setView('village');
  else{selected='hq';renderSidebar();}
}
addEventListener('keydown',e=>{if(e.key==='Escape')cancel();if(e.target.matches('input,textarea'))return;if(e.key==='+')renderer.camera.zoom=Math.min(1.8,renderer.camera.zoom+.1);if(e.key==='-')renderer.camera.zoom=Math.max(.5,renderer.camera.zoom-.1);});
new ResizeObserver(()=>renderer.resize()).observe($('#scene'));
addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
addEventListener('appinstalled',()=>{installPrompt=null;toast('Auralis Frontier instalado.');});
addEventListener('pagehide',()=>save());
document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{E.advance(state);lastFrame=performance.now();updateResources();renderSidebar();renderPanel();}});
if('serviceWorker'in navigator&&!globalThis.Capacitor?.isNativePlatform?.()&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>toast('El modo sin conexión no se pudo activar. Puedes seguir jugando en línea.'));
let lastFrame=performance.now();
function frame(t){const dt=Math.min(.1,(t-lastFrame)/1000);lastFrame=t;
  if(!document.hidden){
    if(state.battle){renderer.addShots(E.battleStep(state,dt));$('#battle-timer').textContent=time(180-state.battle.elapsed);if(state.battle.outcome)showBattleResult();}
    if(state.raid){renderer.addShots(E.raidStep(state,dt));$('#battle-bar').hidden=false;$('#retreat-btn').hidden=true;$('#battle-timer').textContent=time(180-state.raid.elapsed);if(state.raid.outcome&&!finishedShown){finishedShown=true;openModal(modalHead('DEFENSA DE AURORA',state.raid.outcome==='victory'?'Aurora sigue en pie.':'Aurora necesita reconstruirse.')+`<p>${state.raid.outcome==='victory'?'Has repelido a los invasores. La colonia te recompensa con 150 áureos.':'El Eclipse saqueará el 15% de tus áureos. Repara los edificios dañados y construye más defensas.'}</p><button class="primary" data-action="finish-raid">VOLVER A LA BASE ${icon('arrow')}</button>`);}}
    if(Date.now()-lastUi>1000){
      const before=state.offers.length,jobs=state.jobs.length,construction=state.buildings.filter(b=>b.readyAt).length;E.advance(state);updateResources();
      if(before!==state.offers.length||(view==='army'&&jobs!==state.jobs.length)||(view==='village'&&before!==state.offers.length))renderPanel();
      if(construction!==state.buildings.filter(b=>b.readyAt).length){renderSidebar();if($('#modal').open&&$('#modal [data-action="upgrade"]'))buildingModal($('#modal [data-action="upgrade"]').dataset.id);}
      if((state.battle||state.raid)&&!$('#modal').open)renderSidebar();
      if(!state.battle&&!state.raid&&Date.now()>=state.nextRaidAt&&!$('#modal').open){cancel();setView('base');E.startRaid(state);$('#field-eyebrow').textContent='ALERTA · TU BASE ESTÁ BAJO ATAQUE';$('#field-title').textContent='Defiende Aurora.';$('#field-subtitle').textContent='Las torres, los santuarios y la guarnición defienden tu territorio.';$('#scene-hint').textContent='Defensa automática · Protege tu centro de mando';finishedShown=false;renderDock();renderSidebar();save();toast('¡El Eclipse está atacando tu base!');}
      $$('[data-queue-time]').forEach(el=>el.textContent=time((Number(el.dataset.queueTime)-Date.now())/1000));
      $$('[data-building-timer]').forEach(el=>el.textContent='En obras: '+time((Number(el.dataset.buildingTimer)-Date.now())/1000));
      $$('[data-npc-time]').forEach(el=>el.textContent='Se marcha en '+time((Number(el.dataset.npcTime)-Date.now())/1000));
      if($('#raid-countdown'))$('#raid-countdown').textContent=time((state.nextRaidAt-Date.now())/1000);
      if($('#npc-countdown'))$('#npc-countdown').textContent=time((state.nextNpcAt-Date.now())/1000);
      // Re-evaluate actions as passive production becomes affordable.
      $$('[data-action="fulfill"]').forEach(el=>{const o=state.offers.find(o=>o.id===Number(el.dataset.id));el.disabled=!o||state.resources[o.resource]<o.amount;});
      $$('[data-action="trade"]').forEach(el=>el.disabled=state.resources[el.dataset.resource]<50);
      if(Date.now()-lastSave>5000)save();lastUi=Date.now();
    }
    renderer.draw(state,{selected,placement,terrainTool,moving,deployType});
  }
  requestAnimationFrame(frame);
}
updateResources();renderSidebar();renderDock();
if(state.battle)restoreBattleUi();
if(!state.tutorialSeen)guide();
if(corrupt)toast('Se recuperó una partida dañada. Su copia original se conserva en el almacenamiento local.');
requestAnimationFrame(frame);
